#include <stdint.h>
#include <stm32f4xx.h>
#include <stdio.h>



#if !defined(__SOFT_FP__) && defined(__ARM_FP)
#warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif





/*varible definition*/

volatile uint8_t  flag = 0;
volatile uint16_t counter_exti =0;
volatile uint8_t increment_counter =0;



/*functions head*/

void pines(void);
void blinky(void);
void exti_1(void);




/* funcion main ......*/
int main(void){
	pines();
	blinky();
	exti_1();



	while(1){
		if(flag){
			flag = 0;
			GPIOH->ODR ^= GPIO_ODR_OD1;

		}
		if(increment_counter ==1 ){
			counter_exti++;
			increment_counter=0;

		}
	}


}

void pines(void){
	// PRENDEMOS LOS RELOJES NECESARIOS

	RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOBEN);// ESTAN EN EL MISMO BUS
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;

	RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOCEN);//GPIOC
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

	RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIODEN);//GPIOD
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIODEN;


	//configuracion puertos generales- SALIDA
	//PB

	GPIOB->MODER &= ~(GPIO_MODER_MODE7 | GPIO_MODER_MODE8 | GPIO_MODER_MODE9);//LIPIEZA DE LOS PUERTOS EN REGISTRO MODER
	GPIOB->MODER |= (GPIO_MODER_MODE7_0 | GPIO_MODER_MODE8_0 | GPIO_MODER_MODE9_0);// ACTIVACIOND DE PUERTOS EN REGISTRO MODDER DE BER 10

	GPIOB->OTYPER &= ~(GPIO_OTYPER_OT7 | GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9 );//LIPIEZA DE LOS PUERTOS EN REGISTRO OTIPER

	GPIOB->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR7 | GPIO_OSPEEDER_OSPEEDR8 | GPIO_OSPEEDER_OSPEEDR9);//LIPIEZA DE LOS PUERTOS EN REGISTRO OSSPEDEER
	GPIOB->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR7_1 | GPIO_OSPEEDER_OSPEEDR8_1 | GPIO_OSPEEDER_OSPEEDR9_1);// PONER 10 EN LA POSCION 14  PARA FAST MODE

	GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD7 | GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9);	// LIMPEZA DE PUERTO  PUPDR - SE DEJA EN 00

	GPIOB->ODR &= ~(GPIO_ODR_ODR_7 | GPIO_ODR_ODR_8  | GPIO_ODR_ODR_9); //LIMPESZA DEL PUERTO ODR
	GPIOB->ODR |= (GPIO_ODR_ODR_7 | GPIO_ODR_ODR_8 | GPIO_ODR_ODR_9);// ACTIVACION DEL PUERTO OD SE DEBE POR EN 1 PARA LA SALIDA - SE COMINEZA PAGADO


	//configuracion puertos generales- SALIDA
	//PC

	GPIOC->MODER &= ~(GPIO_MODER_MODE6 | GPIO_MODER_MODE8 | GPIO_MODER_MODE9 | GPIO_MODER_MODE10| GPIO_MODER_MODE11 | GPIO_MODER_MODE12 | GPIO_MODER_MODE13);//LIPIEZA DE LOS PUERTOS EN REGISTRO MODER
	GPIOC->MODER |= (GPIO_MODER_MODE6_0 | GPIO_MODER_MODE8_0 | GPIO_MODER_MODE9_0 | GPIO_MODER_MODE10_0 | GPIO_MODER_MODE11_0 | GPIO_MODER_MODE12_0 | GPIO_MODER_MODE13_0);// ACTIVACIOND DE PUERTOS EN REGISTRO MODDER DE BER 10

	GPIOC->OTYPER &= ~(GPIO_OTYPER_OT6 | GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9 | GPIO_OTYPER_OT10 | GPIO_OTYPER_OT11 | GPIO_OTYPER_OT12 | GPIO_OTYPER_OT13 );//LIPIEZA DE LOS PUERTOS EN REGISTRO OTIPER

	GPIOC->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR6  | GPIO_OSPEEDER_OSPEEDR8 | GPIO_OSPEEDER_OSPEEDR9 | GPIO_OSPEEDER_OSPEEDR10 | GPIO_OSPEEDER_OSPEEDR11 | GPIO_OSPEEDER_OSPEEDR12 | GPIO_OSPEEDER_OSPEEDR13);//LIPIEZA DE LOS PUERTOS EN REGISTRO OSSPEDEER
	GPIOC->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR6_1  | GPIO_OSPEEDER_OSPEEDR8_1 | GPIO_OSPEEDER_OSPEEDR9_1 | GPIO_OSPEEDER_OSPEEDR10_1 | GPIO_OSPEEDER_OSPEEDR11_1 | GPIO_OSPEEDER_OSPEEDR12_1 | GPIO_OSPEEDER_OSPEEDR13_1);// PONER 10 EN LA POSCION 14  PARA FAST MODE

	GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD6 | GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9 | GPIO_PUPDR_PUPD10 | GPIO_PUPDR_PUPD11 | GPIO_PUPDR_PUPD12 | GPIO_PUPDR_PUPD13);	// LIMPEZA DE PUERTO  PUPDR - SE DEJA EN 00

	GPIOC->ODR &= ~(GPIO_ODR_ODR_6 | GPIO_ODR_ODR_8  | GPIO_ODR_ODR_9 | GPIO_ODR_ODR_10  | GPIO_ODR_ODR_11| GPIO_ODR_ODR_12  | GPIO_ODR_ODR_13); //LIMPESZA DEL PUERTO ODR
	GPIOC->ODR |= (GPIO_ODR_ODR_6 | GPIO_ODR_ODR_8  | GPIO_ODR_ODR_9 | GPIO_ODR_ODR_10  | GPIO_ODR_ODR_11| GPIO_ODR_ODR_12  | GPIO_ODR_ODR_13);// ACTIVACION DEL PUERTO OD SE DEBE POR EN 1 PARA LA SALIDA - SE COMINEZA PAGADO

	//configuracion puertos generales- SALIDA
	//PD

	GPIOD->MODER &= ~(GPIO_MODER_MODE2);//LIPIEZA DE LOS PUERTOS EN REGISTRO MODER
	GPIOD->MODER |= (GPIO_MODER_MODE2_0);// ACTIVACIOND DE PUERTOS EN REGISTRO MODDER DE BER 10

	GPIOD->OTYPER &= ~(GPIO_OTYPER_OT2);//LIPIEZA DE LOS PUERTOS EN REGISTRO OTIPER

	GPIOD->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR2);//LIPIEZA DE LOS PUERTOS EN REGISTRO OSSPEDEER
	GPIOD->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR2_1);// PONER 10 EN LA POSCION 14  PARA FAST MODE

	GPIOD->PUPDR &= ~(GPIO_PUPDR_PUPD2);	// LIMPEZA DE PUERTO  PUPDR - SE DEJA EN 00

	GPIOD->ODR &= ~(GPIO_ODR_ODR_2); //LIMPESZA DEL PUERTO ODR
	GPIOD->ODR |= (GPIO_ODR_ODR_2);// ACTIVACION DEL PUERTO OD SE DEBE POR EN 1 PARA LA SALIDA - SE COMINEZA PAGADO

	//CONFIGURACION PINES ENTRADA SIMPLE
	//PIN B (PB0)

	GPIOB->MODER &= ~(GPIO_MODER_MODE0);
	GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD0);
	GPIOB->PUPDR |= (GPIO_PUPDR_PUPD0);
	//PIN C (PC0)
	GPIOC->MODER &= ~(GPIO_MODER_MODE0);
	GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD0);
	GPIOC->PUPDR |= (GPIO_PUPDR_PUPD0);
}

void blinky(void){

	RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOHEN);// ACTIVACION DEL GPIO H DONDE YACE EL PH1
	RCC->AHB1ENR |= RCC_AHB1ENR_GPIOHEN;

	GPIOH->MODER &= ~(GPIO_MODER_MODE1);//LIPIEZA DE LOS PUERTOS EN REGISTRO MODER
	GPIOH->MODER |= (GPIO_MODER_MODE1_0);// ACTIVACIOND DE PUERTOS EN REGISTRO MODDER DE SER 10

	GPIOH->OTYPER &= ~(GPIO_OTYPER_OT1);//LIPIEZA DE LOS PUERTOS EN REGISTRO OTYPER

	GPIOH->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR1);//LIPIEZA DE LOS PUERTOS EN REGISTRO OSSPEDEER
	GPIOH->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR1_1);// PONER 10 EN LA POSCION 14  PARA FAST MODE

	GPIOH->PUPDR &= ~(GPIO_PUPDR_PUPD1);	// LIMPEZA DE PUERTO  PUPDR - SE DEJA EN 00

	GPIOH->ODR &= ~(GPIO_ODR_ODR_1); //LIMPESZA DEL PUERTO ODR
	GPIOH->ODR |= (GPIO_ODR_ODR_1);// ACTIVACION DEL PUERTO OD SE DEBE POR EN 1 PARA LA SALIDA

	//CONFIGURACION DEL TIMMER 2

	//ACTIVACION DEL BUS DONDE LLACE EL TIM2

	RCC->APB1ENR &= ~(RCC_APB1ENR_TIM2EN);//SEÑAL DE RELOJ DEL REISTRO
	RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;

	TIM2->PSC = 16000-1;//PROGRAMACION DEL RECALES PRA QUE SEA 1S
	TIM2->ARR = 250-1; //1s

	TIM2->CNT = 0; //Contador en 0 (inicio)

	TIM2->DIER &= ~(TIM_DIER_UIE);
	TIM2->DIER |= TIM_DIER_UIE;

	__NVIC_EnableIRQ(TIM2_IRQn);

	TIM2->CR1 &= ~(TIM_CR1_DIR);

	TIM2->CR1 &= ~(TIM_CR1_ARPE);
	TIM2->CR1 |= TIM_CR1_ARPE;
	TIM2->CR1 |= TIM_CR1_CEN;

}

void TIM2_IRQHandler(void){
	//VERIFICACION QUE SE GENERA LA INTERUPCIOM
	if (TIM2->SR & TIM_SR_UIF){
		TIM2->SR &= ~ TIM_SR_UIF;// REALIZACION DE ACCION DE RESPUESTA
		flag = 1;
	}
}

void exti_1(void){
	RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;

	SYSCFG->EXTICR[1] &= ~(SYSCFG_EXTICR1_EXTI0);
	SYSCFG->EXTICR[1] |= (SYSCFG_EXTICR1_EXTI0_PB);

	EXTI->FTSR |= EXTI_FTSR_TR0;

	NVIC_EnableIRQ(EXTI0_IRQn);

	EXTI->PR |= EXTI_PR_PR0;

	EXTI->IMR |= EXTI_IMR_IM0;


}
//ISR PARA EL EXTI

void EXTI0_IRQHandler(void){
	if(EXTI->PR && EXTI_PR_PR0){
		EXTI->PR |= EXTI_PR_PR0;
		increment_counter=1;




	}

}


